1→export interface Session {
  token: string;
  expiresAt: string;
}

const SESSION_KEY = "exchange.session.v1";
const EXPIRATION_NOTICE_KEY = "exchange.session-expired.v1";

let memorySession: Session | null = null;
10→
function isSession(value: unknown): value is Session {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Partial<Session>;
  return (
    typeof candidate.token === "string" &&
    candidate.token.length > 0 &&
    typeof candidate.expiresAt === "string" &&
    Number.isFinite(Date.parse(candidate.expiresAt))
  );
20→}

export function saveSession(session: Session): void {
  localStorage.setItem(SESSION_KEY, JSON.stringify(session));
  memorySession = session;
  sessionStorage.removeItem(EXPIRATION_NOTICE_KEY);
}

export function readPersistedSession(): Session | null {
  if (memorySession !== null) return memorySession;
30→  const serialized = localStorage.getItem(SESSION_KEY);
  if (serialized === null) return null;

  try {
    const parsed: unknown = JSON.parse(serialized);
    if (!isSession(parsed)) {
      clearSession();
      return null;
    }
    memorySession = parsed;
40→    return parsed;
  } catch {
    clearSession();
    return null;
  }
}

export function clearSession(): void {
  memorySession = null;
  localStorage.removeItem(SESSION_KEY);
50→}

export function isExpired(session: Session, now = Date.now()): boolean {
  return Date.parse(session.expiresAt) <= now;
}

export function markExpirationNotice(): void {
  sessionStorage.setItem(EXPIRATION_NOTICE_KEY, "1");
}

60→export function takeExpirationNotice(): boolean {
  const exists = sessionStorage.getItem(EXPIRATION_NOTICE_KEY) === "1";
  sessionStorage.removeItem(EXPIRATION_NOTICE_KEY);
  return exists;
}

export function resetSessionMemoryForTests(): void {
  memorySession = null;
}

