await (async (page) => {
  const browser = page.context().browser();
  const ctx = await browser.newContext();
  const p = await ctx.newPage();
  await p.setViewportSize({ width: 1280, height: 800 });
  await p.goto('http://127.0.0.1:4203/login', { waitUntil: 'domcontentloaded' });
  await p.waitForSelector('#email');

  let aborted = 0;
  await p.route('**/api/v1/auth/login', async (route) => {
    aborted += 1;
    await route.abort('internetdisconnected');
  });

  await p.getByLabel('Email').fill('eval-web@test.local');
  await p.getByLabel('Contrase\u00f1a').fill('EvalWeb123!');
  await p.getByRole('button', { name: 'Ingresar' }).click();
  await p.waitForTimeout(1500);

  const afterAbort = {
    href: p.url(),
    aborted,
    notices: await p.locator('.notice, [role=alert]').allTextContents(),
    email: await p.locator('#email').inputValue(),
    password: await p.locator('#password').inputValue(),
    heading: await p.locator('h2').textContent().catch(() => null),
    buttonDisabled: await p.getByRole('button', { name: /Ingresar/ }).isDisabled(),
    bodyText: await p.locator('body').innerText(),
  };
  await p.screenshot({ path: 'evidencia/AT-10-01-08-1.png', scale: 'css' });

  let afterRetry = null;
  try {
    await p.unroute('**/api/v1/auth/login');
    const respPromise = p.waitForResponse(r => r.url().includes('/api/v1/auth/login') && r.request().method() === 'POST', { timeout: 8000 });
    await p.getByRole('button', { name: /Ingresar/ }).click();
    const resp = await respPromise;
    afterRetry = { status: resp.status(), postData: resp.request().postData(), href: p.url() };
    await p.waitForTimeout(1000);
    afterRetry.href = p.url();
  } catch (e) {
    afterRetry = { error: String(e), href: p.url(), abortedAfter: aborted };
  }

  await ctx.close();
  return {
    afterAbort: { ...afterAbort, hasStackLike: /TypeError|at \w+|stack:|ECONNREFUSED|Failed to fetch/i.test(afterAbort.bodyText) },
    afterRetry,
  };
})(page);
